import React, {type FC} from 'react';

import {getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {IconRefuge, type IconRefugeProps} from '../IconRefuge';

import {cnStatusIcon} from './StatusIcon.classname';
import {defaultMessages} from './i18n';
import type {GoalStatus, IssueStatus, MetaEntityStatus} from './types';
import {getSvgForStatusType} from './utils';

import './StatusIcon.scss';

export type StatusIconProps = Partial<Pick<IconRefugeProps, 'containerClassName' | 'title'>> & {
    statusType?: IssueStatus | MetaEntityStatus | GoalStatus;
    size?: number;
    className?: string;
};

export const StatusIcon: FC<StatusIconProps> = ({
    className,
    containerClassName,
    statusType,
    size = 16,
    title,
}) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);
    const ariaLabel = title ? t('status-label', {status: title}) : undefined;

    return (
        <IconRefuge
            containerClassName={containerClassName}
            className={cnStatusIcon({status: statusType}, className)}
            data={getSvgForStatusType(statusType)}
            refugeSize={size}
            title={title}
            aria-label={ariaLabel}
            aria-hidden={!title || undefined}
        />
    );
};

StatusIcon.displayName = 'StatusIcon';
